INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (200, 'Español', 'ONCE', 1, 'Participa en escenarios académicos, políticos y culturales; asumiendo una posición crítica y propositiva frente a los discursos que le presentan los distintos medios de comunicación y otras fuentes de información.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (201, 'Español', 'ONCE', 2, 'Expresa, con sentido crítico, cómo se articulan los códigos verbales y no verbales en diversas manifestaciones humanas y da cuenta de sus implicaciones culturales, sociales e ideológicas.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
