INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (207, 'Español', 'ONCE', 8, 'Produce textos académicos a partir de procedimientos sistemáticos de corrección lingüística, atendiendo al tipo de texto y al contexto comunicativo.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (208, 'Ciencias Naturales', 'PRIMERO', 1, 'Comprende que los sentidos le permiten percibir algunas características de los objetos que nos rodean (temperatura, sabor, sonidos, olor, color, texturas y formas).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (209, 'Ciencias Naturales', 'PRIMERO', 2, 'Comprende que existe una gran variedad de materiales y que éstos se utilizan para distintos fines, según sus características (longitud, dureza, flexibilidad, permeabilidad al agua, solubilidad, ductilidad, maleabilidad, color, sabor, textura).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (210, 'Ciencias Naturales', 'PRIMERO', 3, 'Comprende que los seres vivos (plantas y animales) tienen características comunes (se alimentan, respiran, tienen un ciclo de vida, responden al entorno) y los diferencia de los objetos inertes.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (211, 'Ciencias Naturales', 'PRIMERO', 4, 'Comprende que su cuerpo experimenta constantes cambios a lo largo del tiempo y reconoce a partir de su comparación que tiene características similares y diferentes a las de sus padres y compañeros.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (212, 'Ciencias Naturales', 'SEGUNDO', 1, 'Comprende que una acción mecánica (fuerza) puede producir distintas deformaciones en un objeto, y que este resiste a las fuerzas de diferente modo, de acuerdo con el material del que está hecho.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (213, 'Ciencias Naturales', 'SEGUNDO', 2, 'Comprende que las sustancias pueden encontrarse en distintos estados (sólido, líquido y gaseoso).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (214, 'Ciencias Naturales', 'SEGUNDO', 3, 'Comprende la relación entre las características físicas de plantas y animales con los ambientes en donde viven, teniendo en cuenta sus necesidades básicas (luz, agua, aire, suelo, nutrientes, desplazamiento y protección).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (215, 'Ciencias Naturales', 'SEGUNDO', 4, 'Explica los procesos de cambios físicos que ocurren en el ciclo de vida de plantas y animales de su entorno, en un período de tiempo determinado.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (216, 'Ciencias Naturales', 'TERCERO', 1, 'Comprende la forma en que se propaga la luz a través de diferentes materiales (opacos, transparentes como el aire, translúcidos como el papel y reflectivos como el espejo).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (217, 'Ciencias Naturales', 'TERCERO', 2, 'Comprende la forma en que se produce la sombra y la relación de su tamaño con las distancias entre la fuente de luz, el objeto interpuesto y el lugar donde se produce la sombra.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (218, 'Ciencias Naturales', 'TERCERO', 3, 'Comprende la naturaleza (fenómeno de la vibración) y las características del sonido (altura, timbre, intensidad) y que este se propaga en distintos medios (sólidos, líquidos, gaseosos).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (219, 'Ciencias Naturales', 'TERCERO', 4, 'Comprende la influencia de la variación de la temperatura en los cambios de estado de', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (220, 'Ciencias Naturales', 'TERCERO', 5, 'Explica la influencia de los factores abióticos (luz, temperatura, suelo y aire) en el desarrollo de los factores bióticos (fauna y flora) de un ecosistema.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (221, 'Ciencias Naturales', 'TERCERO', 6, 'Comprende las relaciones de los seres vivos con otros organismos de su entorno (intra e interespecíficas) y las explica como esenciales para su supervivencia en un ambiente determinado.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (222, 'Ciencias Naturales', 'CUARTO', 1, 'Comprende que la magnitud y la dirección en que se aplica una fuerza puede producir cambios en la forma como se mueve un objeto (dirección y rapidez).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (223, 'Ciencias Naturales', 'CUARTO', 2, 'Comprende los efectos y las ventajas de utilizar máquinas simples en diferentes tareas que requieren la aplicación de una fuerza.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (224, 'Ciencias Naturales', 'CUARTO', 3, 'Comprende que el fenómeno del día y la noche se debe a que la Tierra rota sobre su eje y en consecuencia el sol sólo ilumina la mitad de su superficie.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (225, 'Ciencias Naturales', 'CUARTO', 4, 'Comprende que las fases de la Luna se deben a la posición relativa del Sol, la Luna y la Tierra a lo largo del mes.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (226, 'Ciencias Naturales', 'CUARTO', 5, 'Comprende que existen distintos tipos de mezclas (homogéneas y heterogéneas) que de acuerdo con los materiales que las componen pueden separarse mediante diferentes técnicas (filtración, tamizado, decantación, evaporación).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (227, 'Ciencias Naturales', 'CUARTO', 6, 'Comprende que los organismos cumplen distintas funciones en cada uno de los niveles tróficos y que las relaciones entre ellos pueden representarse en cadenas y redes alimenticias.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (228, 'Ciencias Naturales', 'CUARTO', 7, 'Comprende que existen distintos tipos de ecosistemas (terrestres y acuáticos) y que sus características físicas (temperatura, humedad, tipos de suelo, altitud) permiten que habiten en ellos diferentes seres vivos.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (229, 'Ciencias Naturales', 'QUINTO', 1, 'Comprende que un circuito eléctrico básico está formado por un generador o fuente (pila), conductores (cables) y uno o más dispositivos (bombillos, motores, timbres), que deben estar conectados apropiadamente (por sus dos polos) para que funcionen y produzcan diferentes efectos.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (230, 'Ciencias Naturales', 'QUINTO', 2, 'Comprende que algunos materiales son buenos conductores de la corriente eléctrica y otros no (denominados aislantes) y que el paso de la corriente siempre genera calor.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (231, 'Ciencias Naturales', 'QUINTO', 3, 'Comprende que los sistemas del cuerpo humano están formados por órganos, tejidos y células y que la estructura de cada tipo de célula está relacionada con la función del tejido que forman.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (232, 'Ciencias Naturales', 'QUINTO', 4, 'Comprende que en los seres humanos (y en muchos otros animales) la nutrición involucra el funcionamiento integrado de un conjunto de sistemas de órganos: digestivo, respiratorio y circulatorio.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (233, 'Ciencias Naturales', 'SEXTO', 1, 'Comprende cómo los cuerpos pueden ser cargados eléctricamente asociando esta carga a efectos de atracción y repulsión.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (234, 'Ciencias Naturales', 'SEXTO', 2, 'Comprende que la temperatura (T) y la presión (P) influyen en algunas propiedades fisicoquímicas (solubilidad, viscosidad, densidad, puntos de ebullición y fusión) de las sustancias, y que estas pueden ser aprovechadas en las técnicas de separación de mezclas.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (235, 'Ciencias Naturales', 'SEXTO', 3, 'Comprende la clasificación de los materiales a partir de grupos de sustancias (elementos y compuestos) y mezclas (homogéneas y heterogéneas).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (236, 'Ciencias Naturales', 'SEXTO', 4, 'Comprende algunas de las funciones básicas de la célula (transporte de membrana, obtención de energía y división celular) a partir del análisis de su estructura.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
