INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (238, 'Ciencias Naturales', 'SEPTIMO', 1, 'Comprende las formas y las transformaciones de energía en un sistema mecánico y la manera como, en los casos reales, la energía se disipa en el medio (calor, sonido).', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (239, 'Ciencias Naturales', 'SEPTIMO', 2, 'Explica cómo las sustancias se forman a partir de la interacción de los elementos y que estos se encuentran agrupados en un sistema periódico.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
