INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (246, 'Ciencias Naturales', 'OCTAVO', 5, 'Analiza la reproducción (asexual, sexual) de distintos grupos de seres vivos y su importancia para la preservación de la vida en el planeta.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (247, 'Ciencias Naturales', 'NOVENO', 1, 'Comprende que el movimiento de un cuerpo, en un marco de referencia inercial dado, se puede describir con gráficos y predecir por medio de expresiones matemáticas.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
