INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (249, 'Ciencias Naturales', 'NOVENO', 3, 'Analiza las relaciones cuantitativas entre solutos y solventes, así como los factores que afectan la formación de soluciones.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (250, 'Ciencias Naturales', 'NOVENO', 4, 'Comprende la forma en que los principios genéticos mendelianos y post-mendelianos explican la herencia y el mejoramiento de las especies existentes.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
INSERT INTO dba (id_dba, area, grado, numero_dba, enunciado, version_curricular, estado, created_at, updated_at) VALUES (251, 'Ciencias Naturales', 'NOVENO', 5, 'Explica la forma como se expresa la información genética contenida en el –ADN–, relacionando su expresión con los fenotipos de los organismos y reconoce su capacidad de modificación a lo largo del tiempo (por mutaciones y otros cambios), como un factor determinante en la generación de diversidad del planeta y en la evolución de las especies.', '2016', 'ACTIVO', NOW(), NOW()) ON CONFLICT (id_dba) DO UPDATE SET enunciado = EXCLUDED.enunciado, area = EXCLUDED.area, grado = EXCLUDED.grado, numero_dba = EXCLUDED.numero_dba, version_curricular = EXCLUDED.version_curricular, estado = EXCLUDED.estado;
