INSERT INTO evidencias_dba (id_evidencia_dba, id_dba, descripcion, orden, estado, created_at) VALUES (519, 33, 'Describe y desarrolla estrategias para calcular sumas y restas basadas en descomposiciones aditivas y multiplicativas. 1 No se espera en este nivel escolar un estudio profundo de los números racionales como sistema numérico, sino una primera aproximación a las cantidades -generalmente llamada en los grados de primaria como fraccionarios- que expresan una razón entre otras dos cantidades, y cuyo resultado no siempre da un número exacto de unidades. Aunque estrictamente hablando los conceptos representados por estas expresiones no son coincidentes se acompañará la palabra “racionales” de la palabra “fraccionario” escrita entre paréntesis.', 2, 'ACTIVO', NOW()) ON CONFLICT (id_evidencia_dba) DO UPDATE SET descripcion = EXCLUDED.descripcion, orden = EXCLUDED.orden, estado = EXCLUDED.estado;
